namespace CubeSolverPro.Core.Cube;
public sealed record PuzzleInfo(string Id,string Name,int Size,string Method,int? MoveCount=null); public sealed record ScrambleResult(string Puzzle,string Text,PuzzleCube State);
public static class Scrambles {public static readonly IReadOnlyDictionary<string,PuzzleInfo> Puzzles=new[]{new PuzzleInfo("222","2x2x2",2,"random-state"),new("333","3x3x3",3,"random-state"),new("444","4x4x4",4,"random-move",45),new("555","5x5x5",5,"random-move",60),new("666","6x6x6",6,"random-move",80),new("777","7x7x7",7,"random-move",100)}.ToDictionary(x=>x.Id); public static IReadOnlyList<Move> RandomMoveScramble(int size,int length,Random? random=null){random??=Random.Shared;var width=size<=3?1:size<=5?2:3;var moves=new List<Move>();Face? previous=null,before=null;while(moves.Count<length){var face=Geometry.Faces[random.Next(6)];if(face==previous||previous.HasValue&&Geometry.Axis(face)==Geometry.Axis(previous.Value)&&face==before)continue;var depth=random.Next(1,width+1);moves.Add(new(face,new(MoveSpanKind.Layers,1,depth),random.Next(1,4)));before=previous;previous=face;}return moves;} public static ScrambleResult Generate(string puzzle){var p=Puzzles[puzzle];var count=p.MoveCount??(p.Size==2?11:25);var moves=RandomMoveScramble(p.Size,count);var text=Notation.FormatAlg(moves);return new(puzzle,text,PuzzleCube.Solved(p.Size).ApplyAlg(text));}}
